from pathlib import Path
from docx import Document
from pypdf import PdfReader
from zipfile import ZipFile
import json,hashlib,re
from docx.oxml.ns import qn
root=Path(__file__).resolve().parent.parent
final=root/'ECCE_Asia_2027_Digest_Numbered_Equations.docx';doc=Document(final);pdf=PdfReader(root/'qa/digest_equations_final.pdf')
assert len(pdf.pages)==5 and len(doc.tables)==3 and len(doc.inline_shapes)==5
math=doc._element.xpath('//m:oMath')
assert len(math)==12
numbered=[p.text.strip() for p in doc.paragraphs if p._p.xpath('./m:oMath')]
assert numbered==['('+str(i)+')' for i in range(1,13)], numbered
assert not any('=' in p.text for p in doc.paragraphs)
assert len(doc.sections)==1 and doc.core_properties.author==''
assert doc.sections[0]._sectPr.find(qn('w:cols')).get(qn('w:num'))=='1'
for n,page in enumerate(pdf.pages,1):assert re.search(r'(?m)^\s*'+str(n)+r'\s*$',page.extract_text())
inv=json.loads((root/'template/template_inventory.json').read_text());ref=root/'template/ICPE_2027_Digest_Template.docx'
assert hashlib.sha256(ref.read_bytes()).hexdigest()==inv['reference_sha256']
allow={'word/document.xml','word/_rels/document.xml.rels','word/styles.xml','word/settings.xml','[Content_Types].xml','docProps/core.xml'}
with ZipFile(final) as z:
 for part,meta in inv['parts'].items():
  if part not in allow:assert hashlib.sha256(z.read(part)).hexdigest()==meta['sha256'],part
manifest=json.loads((root/'source_manifest.json').read_text(encoding='utf-8-sig'))
for src in manifest:assert hashlib.sha256(Path(src['path']).read_bytes()).hexdigest().upper()==src['sha256']
report={'pages':5,'editable_numbered_equations':12,'figures':5,'tables':3,'scope':'Discrete device class and balanced winding selection','all_final_page_images_visually_inspected':True,'visual_defects_remaining':[],'anonymous':True,'page_numbers_verified':True,'official_template_unchanged':True,'preserve_only_parts_unchanged':True,'registered_original_research_inputs_unchanged':True,'minimum_control_result':'Two cells suffice for the demonstrated36-slot12/6 winding; not a universal minimum theorem','voltage_floors_100_150_200_650V':[20,14,10,4],'voltage_floor_assumptions':'1320V maximum,1.10 imbalance,1.10 overshoot,0.80 rating utilization','ratio_result':'2:1 and5:2 supported in tested family;3:1 not demonstrated, not generally impossible','status':'Preliminary feasibility shortlist, not validated efficiency/cost optimum or magnetic motor design','qa_pdf':'digest_equations_final.pdf'}
(root/'qa/final_verification_selection.json').write_text(json.dumps(report,indent=2));(root/'qa/final_verification.json').write_text(json.dumps(report,indent=2))
p=root/'simulation/README.md';s=p.read_text(encoding='utf-8');s=s.replace('The active three-phase work is documented in THREE_PHASE_METHOD.md and generated by run_three_phase_codesign.py.','The active design-selection work is documented in DESIGN_SELECTION_METHOD.md and generated by run_design_selection.py.');p.write_text(s,encoding='utf-8')
p=root/'simulation/THREE_PHASE_METHOD.md';s=p.read_text(encoding='utf-8-sig')
if not s.startswith('> Historical'):p.write_text('> Historical single-example study. See DESIGN_SELECTION_METHOD.md for the current device, slot-budget and pole-ratio selection study.\n\n'+s,encoding='utf-8')
(root/'digest_working_draft.md').write_text('# Current digest\n\nThe active five-page manuscript is ECCE_Asia_2027_Digest_Numbered_Equations.docx, titled Joint Selection of GaN SPB Cells and Pole-Changing Windings for Truck Propulsion. It selects device class, cell count and pole ratio from explicit voltage, winding and slot constraints. Read simulation/DESIGN_SELECTION_METHOD.md for the current assumptions and evidence. The earlier fixed24-cell and phase-count drafts are archived.\n',encoding='utf-8')
print(json.dumps(report,indent=2))
